ALTER TABLE public.gryt_ticket_events ADD COLUMN environment text NOT NULL DEFAULT 'sandbox' CHECK(environment IN ('sandbox','live'));
ALTER TABLE public.gryt_partner_packages ADD COLUMN environment text NOT NULL DEFAULT 'sandbox' CHECK(environment IN ('sandbox','live'));
ALTER TABLE public.gryt_ticket_events DROP CONSTRAINT gryt_ticket_events_slug_key;
ALTER TABLE public.gryt_ticket_events ADD UNIQUE(environment,slug);
ALTER TABLE public.gryt_payment_orders DROP CONSTRAINT gryt_payment_orders_environment_check;
ALTER TABLE public.gryt_payment_orders ADD CHECK(environment IN ('sandbox','live'));
ALTER TABLE public.payments DROP CONSTRAINT payments_environment_check;
ALTER TABLE public.payments ADD CHECK(environment IN ('sandbox','live'));
CREATE FUNCTION public.gryt_payment_catalog(event_slug text, payment_env text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('products',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'sku',sku,'amount_cents',amount_cents,'description',description)) FROM public.gryt_payment_products WHERE active AND payment_env IN ('sandbox','live')),'[]'::jsonb),'event',(SELECT jsonb_build_object('id',e.id,'slug',e.slug,'name',e.name,'event_date',e.event_date,'location',e.location,'amount_cents',e.amount_cents,'capacity',e.capacity,'remaining',GREATEST(0,e.capacity-COALESCE((SELECT sum(o.quantity) FROM public.gryt_payment_orders o WHERE o.environment=payment_env AND o.item_id=e.id AND o.type='ticket' AND (o.status IN ('paid','pending') OR (o.status='reserved' AND o.expires_at>now()))),0))) FROM public.gryt_ticket_events e WHERE e.active AND e.environment=payment_env AND e.slug=event_slug)) $$;
REVOKE ALL ON FUNCTION public.gryt_payment_catalog(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.gryt_payment_catalog(text,text) TO anon,authenticated,service_role;
CREATE FUNCTION public.gryt_reserve_payment_order(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; available integer; requested integer; result uuid; payment_env text; BEGIN payment_env:=payload->>'environment'; IF payment_env IS NULL OR payment_env NOT IN ('sandbox','live') THEN RAISE EXCEPTION 'INVALID_ENVIRONMENT'; END IF; target:=NULLIF(payload->>'item_id','')::uuid; requested:=(payload->>'quantity')::integer; IF payload->>'type'='ticket' THEN PERFORM 1 FROM public.gryt_ticket_events WHERE id=target AND active AND environment=payment_env FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'EVENT_UNAVAILABLE'; END IF; SELECT capacity-COALESCE((SELECT sum(quantity) FROM public.gryt_payment_orders WHERE item_id=target AND environment=payment_env AND type='ticket' AND (status IN ('paid','pending') OR (status='reserved' AND expires_at>now()))),0) INTO available FROM public.gryt_ticket_events WHERE id=target AND environment=payment_env; IF requested>available THEN RAISE EXCEPTION 'EVENT_SOLD_OUT'; END IF; ELSIF payload->>'type'='partner' THEN PERFORM 1 FROM public.gryt_partner_packages WHERE id=target AND active AND environment=payment_env FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'PACKAGE_UNAVAILABLE'; END IF; IF EXISTS(SELECT 1 FROM public.gryt_payment_orders WHERE item_id=target AND environment=payment_env AND type='partner' AND (status IN ('paid','pending') OR (status='reserved' AND expires_at>now()))) THEN RAISE EXCEPTION 'PACKAGE_ALREADY_RESERVED_OR_PAID'; END IF; END IF; INSERT INTO public.gryt_payment_orders(type,item_id,item,amount_cents,quantity,email,attendee_name,fulfillment,monthly,return_path,environment) VALUES(payload->>'type',target,payload->>'item',(payload->>'amount_cents')::integer,requested,payload->>'email',COALESCE(payload->>'attendee_name',''),COALESCE(payload->>'fulfillment',''),COALESCE((payload->>'monthly')::boolean,false),payload->>'return_path',payment_env) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.gryt_reserve_payment_order(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.gryt_reserve_payment_order(jsonb) TO service_role;